<script setup>
import {computed,ref,watch} from 'vue';
import {money} from '@/sheep/api/pharmacy/common';
import {safeImage} from './guards.js';
const props=defineProps({product:{type:Object,required:true},imageOnly:Boolean,stockUnknown:Boolean,adding:Boolean,cartQty:{type:Number,default:0}});
defineEmits(['unavailable','add','decrease']);const failed=ref(false);watch(()=>props.product.image,()=>failed.value=false);
const image=computed(()=>!props.product.rx&&!failed.value?safeImage(props.product.image):'');
</script>
<template><div v-if="imageOnly" class="product-photo" :class="{missing:!image}"><img v-if="image" :src="image" :alt="product.name+'商品图'" @error="failed=true"><template v-else><Icon :name="product.rx?'lock-keyhole':'image'"/><span>{{product.rx?'处方资料受限':'商品图片暂未提供'}}</span></template></div><article v-else class="product-card" :class="{'rx-card':product.rx}" :data-product="product.id"><a class="product-link" :href="'#detail?id='+product.id" :aria-label="'查看'+product.name+'详情'"><div class="product-photo" :class="{missing:!image}"><img v-if="image" :src="image" :alt="product.name+'商品图'" @error="failed=true"><template v-else><Icon :name="product.rx?'lock-keyhole':'image'"/><span>{{product.rx?'处方资料受限':'商品图片暂未提供'}}</span></template></div><div class="product-body"><span class="tag" :class="{rx:product.rx}">{{product.rx?'Rx 处方药':product.device?'医疗器械':'OTC 非处方'}}</span><h3>{{product.name}}</h3><p>{{product.specification||'规格暂未提供'}}</p></div></a><div class="product-bottom"><div v-if="product.rx"><span class="rx-note">凭处方购买</span><span class="stock">需药师审核后结算</span></div><div v-else><span class="price"><small>¥</small>{{money(product.price).split('.')[0]}}<small class="dec">.{{money(product.price).split('.')[1]}}</small></span><span class="stock" :class="{out:!stockUnknown&&product.stock<=0}">{{stockUnknown?'库存暂不可用':product.stock>0?`有货 · ${product.stock} 件`:'暂无可售库存'}}</span></div><a v-if="product.rx" class="rx-btn" :href="'#rx-submit?drugId='+product.id"><Icon name="file-check-2"/>上传处方购买</a><div v-else-if="cartQty>0" class="qty-stepper"><button type="button" aria-label="减少数量" :disabled="adding" @click="$emit('decrease',product)"><Icon name="minus"/></button><b>{{cartQty}}</b><button type="button" aria-label="增加数量" :disabled="adding||stockUnknown||product.stock<=cartQty" @click="$emit('add',product)"><Icon name="plus"/></button></div><button v-else class="add-btn" :aria-label="'加入购物车：'+product.name" :disabled="adding||stockUnknown||product.stock<=0" @click="$emit('add',product)"><Icon name="plus"/><span>加入<span class="add-tail">购物车</span></span></button></div></article></template>
